static int OpenAfter(int arrive, int finishes)
{
    var board = new Board("Desk");
    board.Arrive(arrive);
    for (int i = 0; i < finishes; i++) board.Finish();
    return board.Open;
}
static int TwoArrivals(int first, int second)
{
    var board = new Board("Desk");
    board.Arrive(first);
    board.Arrive(second);
    return board.Open;
}
